// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.agenticimport com.roshan.persona.brain.context.BrainBudget/** * NOUS — Agentic guardrails. * * Prevents runaway workflows. Checks before each step: *   1. **Max steps** — workflow cannot exceed [maxSteps] (default 10) *   2. **Budget cap** — workflow cannot spend more than [BrainBudget.maxCostUsd] *   3. **Time cap** — workflow cannot exceed [BrainBudget.maxLatencyMs] *   4. **Loop detection** — workflow cannot repeat the same tool call with *      the same params more than [maxRepeats] times (default 2) * * If any check fails, the orchestrator stops the workflow and returns a * [WorkflowTrace] with the appropriate [WorkflowStatus]. * * ## Why These Matter * * Agentic loops are dangerous without guardrails: *   - LLM can get stuck calling the same tool forever (infinite loop) *   - LLM can rack up huge cloud LLM bills (cost runaway) *   - LLM can keep the user waiting forever (time runaway) *   - LLM can keep trying different approaches without converging (step runaway) * * These guardrails are HARD limits — the orchestrator enforces them * unconditionally. The user can adjust them via [BrainBudget] per request. * * @see <a href="docs/spec/module2-spec-review.pdf">§9.4 Guardrails</a> */data class AgenticGuardrails(    /** Maximum number of steps before workflow is force-stopped. */    val maxSteps: Int = DEFAULT_MAX_STEPS,    /** Maximum cost in USD before workflow is force-stopped. */    val maxCostUsd: Float = DEFAULT_MAX_COST_USD,    /** Maximum wall-clock duration in milliseconds. */    val maxDurationMs: Long = DEFAULT_MAX_DURATION_MS,    /** Maximum times the same tool call (same tool + same params) can repeat. */    val maxRepeats: Int = DEFAULT_MAX_REPEATS,) {    init {        require(maxSteps in 1..100) {            "maxSteps must be 1-100, was $maxSteps"        }        require(maxCostUsd >= 0f) {            "maxCostUsd cannot be negative, was $maxCostUsd"        }        require(maxDurationMs in 1_000..3_600_000L) {            "maxDurationMs must be 1s-1h, was $maxDurationMs"        }        require(maxRepeats in 1..10) {            "maxRepeats must be 1-10, was $maxRepeats"        }    }    /**     * Check whether the workflow can continue with another step.     *     * @param currentStepCount number of steps already executed     * @param currentCostUsd total USD spent so far     * @param elapsedMs wall-clock time elapsed since workflow start     * @return [GuardrailDecision.Proceed] or [GuardrailDecision.Stop] with reason     */    fun check(        currentStepCount: Int,        currentCostUsd: Float,        elapsedMs: Long,    ): GuardrailDecision {        if (currentStepCount >= maxSteps) {            return GuardrailDecision.Stop(                reason = "Max steps exceeded ($currentStepCount >= $maxSteps)",                status = WorkflowStatus.MAX_STEPS_EXCEEDED,            )        }        if (currentCostUsd >= maxCostUsd) {            return GuardrailDecision.Stop(                reason = "Budget exceeded (\$${"%.4f".format(currentCostUsd)} >= \$${"%.4f".format(maxCostUsd)})",                status = WorkflowStatus.BUDGET_EXCEEDED,            )        }        if (elapsedMs >= maxDurationMs) {            return GuardrailDecision.Stop(                reason = "Timeout (${elapsedMs}ms >= ${maxDurationMs}ms)",                status = WorkflowStatus.TIMEOUT,            )        }        return GuardrailDecision.Proceed    }    /**     * Check whether a tool call would be a loop (same tool + same params     * repeated too many times).     *     * @param toolId the tool being called     * @param params the params being passed     * @param previousSteps the workflow's previous steps (to detect repeats)     * @return [GuardrailDecision.Proceed] or [GuardrailDecision.Stop] with reason     */    fun checkLoop(        toolId: String,        params: Map<String, String>,        previousSteps: List<WorkflowStep>,    ): GuardrailDecision {        val sameCallCount = previousSteps.count { step ->            val action = step.action            action is AgenticStep.ToolCall &&                action.toolId == toolId &&                action.params == params        }        if (sameCallCount >= maxRepeats) {            return GuardrailDecision.Stop(                reason = "Loop detected: tool '$toolId' called $sameCallCount times with same params (max $maxRepeats)",                status = WorkflowStatus.FAILED,            )        }        return GuardrailDecision.Proceed    }    companion object {        /** Default max steps — 10 is enough for most workflows. */        const val DEFAULT_MAX_STEPS = 10        /** Default max cost — $0.50 per workflow (above this, something's wrong). */        const val DEFAULT_MAX_COST_USD = 0.50f        /** Default max duration — 90 seconds (allows for WebSearch + FetchUrl + LLM). */        const val DEFAULT_MAX_DURATION_MS = 90_000L        /** Default max repeats — same tool+params can repeat 2 times max. */        const val DEFAULT_MAX_REPEATS = 2        /** Strict guardrails — for foreground quick queries. */        val STRICT = AgenticGuardrails(            maxSteps = 5,            maxCostUsd = 0.10f,            maxDurationMs = 15_000L,            maxRepeats = 1,        )        /** Generous guardrails — for background long-running tasks. */        val GENEROUS = AgenticGuardrails(            maxSteps = 25,            maxCostUsd = 2.00f,            maxDurationMs = 300_000L,            maxRepeats = 3,        )    }}/** * Result of a guardrail check. */sealed interface GuardrailDecision {    /** All checks passed — workflow can continue. */    data object Proceed : GuardrailDecision    /** Workflow must stop — guardrail violated. */    data class Stop(        val reason: String,        val status: WorkflowStatus,    ) : GuardrailDecision}